const b = $json.body ?? {};
const text = String(b.text ?? '').trim().slice(0, 2000);
const event = {
  page_id: String(b.site_key ?? ''),
  channel: 'web',
  sender_id: String(b.session_id ?? '').slice(0, 64),
  recipient_id: '',
  mid: String(b.message_id || (Date.now() + '-' + Math.random().toString(36).slice(2))),
  text,
  attachments: [],
  reply_to: null,
  page_url: String(b.page_url ?? '').slice(0, 500),
  timestamp: Date.now(),
  event_kind: text ? 'message' : 'unknown'
};
event.event_b64 = Buffer.from(JSON.stringify(event), 'utf8').toString('base64');
return [{ json: event }];

const j = $input.first().json ?? {};
const def = {
  business: { id: '', name: 'Business', description: '', timezone: 'UTC', languages: ['ru'], communication_tone: '' },
  agent: { name: 'AI Assistant', model: '', temperature: 0.3, memory_window: 12 },
  qualification: {
    required_fields: [
      { key: 'client_name', label: 'Name', description: 'Customer name' },
      { key: 'phone', label: 'Phone', description: 'Phone or messenger contact' },
      { key: 'service_interest', label: 'Service', description: 'Requested service' }
    ],
    optional_fields: [
      { key: 'city', label: 'City', description: 'Customer city' },
      { key: 'budget', label: 'Budget', description: 'Stated budget' },
      { key: 'preferred_time', label: 'Preferred time', description: 'Preferred time' }
    ],
    lead_criteria: [],
    handover_criteria: [],
    handover_on_qualified: true,
    statuses: ['in_progress', 'interested', 'qualified', 'handover', 'not_lead']
  },
  integrations: { instagram_enabled: true, telegram_enabled: true, google_sheets_enabled: false,
                  sheet_id: '', sheet_tab: '', crm_enabled: false, crm_webhook_url: '' },
  notifications: { telegram_chat_id: '', notify_on_qualified_lead: true, notify_on_handover: true,
                   notify_on_error: true, handover_dedupe_hours: 24 },
  behavior: { graph_api_base: 'https://graph.instagram.com/v25.0', mute_hours: 48, debounce_seconds: 5,
              handle_reply_to: true, unsupported_reply_text: 'Извините, я пока могу обрабатывать только текстовые сообщения.',
              ai_error_fallback_text: 'Извините, сейчас не могу ответить. Передам сообщение менеджеру.',
              voice_error_text: 'Не удалось прослушать голосовое. Напишите, пожалуйста, текстом.',
              reply_chunk_limit: 950 }
};
const merge = (base, extra) => {
  const out = Array.isArray(base) ? base.slice() : { ...base };
  if (!extra || typeof extra !== 'object' || Array.isArray(extra)) return out;
  for (const [k, v] of Object.entries(extra)) {
    if (v && typeof v === 'object' && !Array.isArray(v) && base?.[k] && typeof base[k] === 'object' && !Array.isArray(base[k])) out[k] = merge(base[k], v);
    else if (v !== undefined && v !== null) out[k] = v;
  }
  return out;
};
const cfg = merge(def, j.config ?? {});
const norm = (arr) => (Array.isArray(arr) ? arr : []).map(f => typeof f === 'string' ? { key: f, label: f, description: '' } : { key: String(f.key ?? ''), label: String(f.label ?? f.key ?? ''), description: String(f.description ?? '') }).filter(f => f.key);
cfg.qualification.required_fields = norm(cfg.qualification.required_fields);
cfg.qualification.optional_fields = norm(cfg.qualification.optional_fields);
const CORE = ['client_name', 'phone', 'service_interest', 'city', 'budget', 'preferred_time', 'language'];
const requiredKeys = Array.from(new Set(['client_name', 'phone', 'service_interest', ...cfg.qualification.required_fields.map(f => f.key)]));
const optionalKeys = Array.from(new Set(cfg.qualification.optional_fields.map(f => f.key)));
const allFields = [];
const seen = new Set();
for (const f of [...cfg.qualification.required_fields, ...cfg.qualification.optional_fields]) {
  if (seen.has(f.key)) continue;
  seen.add(f.key);
  allFields.push(f);
}
for (const k of CORE) {
  if (seen.has(k)) continue;
  seen.add(k);
  allFields.push({ key: k, label: k, description: k });
}
const labels = Object.fromEntries(allFields.map(f => [f.key, f.label]));
const languages = Array.isArray(cfg.business.languages) && cfg.business.languages.length ? cfg.business.languages : ['ru'];
const event = j.event ?? {};
const text = String(event.text ?? '');
const channel = String(event.channel ?? 'web');
return [{ json: {
  tenant_id: String(j.tenant_id),
  channel,
  page_id: String(event.page_id ?? ''),
  customer_id: String(event.sender_id ?? ''),
  mid: String(event.mid ?? ''),
  event,
  config: cfg,
  languages,
  language_default: languages[0],
  required_keys: requiredKeys,
  optional_keys: optionalKeys,
  lead_labels: labels,
  memory_key: String(j.tenant_id) + ':' + channel + ':' + String(event.sender_id ?? ''),
  text,
  text_b64: Buffer.from(text, 'utf8').toString('base64'),
  __start_ms: Date.now()
} }];

