const ctx = $('Load Context').first().json;
const batch = $input.first().json ?? {};
const base = String(batch.text ?? ctx.text ?? '');
const marker = (ctx.config.behavior.handle_reply_to && ctx.event?.reply_to) ? '[Клиент ответил на сторис/сообщение] ' : '';
return [{ json: { ...ctx, text: (marker + base).trim(), messages_count: Number(batch.messages_count ?? 1) } }];

const ctx = $('Load Context').first().json;
let text = ctx.text;
let messages = 1;
try { const p = $('Prepare Input').first().json; text = p.text ?? text; messages = p.messages_count ?? messages; } catch (e) {}
try { const v = $('Voice Input').first().json; text = v.text ?? text; } catch (e) {}
const fetched = $input.first().json ?? {};
const username = fetched.username ?? $json.username ?? null;
const display_name = fetched.name ?? $json.display_name ?? null;
let lead = {};
try { lead = $('Load Lead').first().json ?? {}; } catch (e) { lead = {}; }
return [{ json: { ...ctx, text, messages_count: messages, username, display_name, lead } }];

const ctx = $('Merge Profile').first().json;
const basePrompt = String($('Load Prompt').first().json.system_prompt ?? '');
const kb = $('Load KB').first().json.kb ?? {};
const cfg = ctx.config;
const fields = [...cfg.qualification.required_fields.map(f => ({ ...f, required: true })),
                ...cfg.qualification.optional_fields.map(f => ({ ...f, required: false }))];
const labels = ctx.lead_labels ?? {};
const known = (ctx.lead && typeof ctx.lead.lead_data === 'object' && ctx.lead.lead_data) ? ctx.lead.lead_data : {};
const requiredKeys = ctx.required_keys;
const missing = requiredKeys.filter(k => !String(known[k] ?? '').trim());

const builtins = {
  languages: (ctx.languages || ['ru']).join(', '),
  language_default: ctx.language_default,
  required_fields: cfg.qualification.required_fields.map(f => labels[f.key] || f.label || f.key).join(', '),
  optional_fields: cfg.qualification.optional_fields.map(f => labels[f.key] || f.label || f.key).join(', ')
};
const missingKb = [];
let rendered = basePrompt.replace(/\{\{\s*(kb:)?([a-zA-Z0-9_]+)\s*\}\}/g, (_, prefix, key) => {
  if (prefix === 'kb:') {
    if (kb[key] === undefined || kb[key] === null || kb[key] === '') { missingKb.push(key); return ''; }
    return String(kb[key]);
  }
  return builtins[key] !== undefined ? String(builtins[key]) : '{{' + key + '}}';
});
const leftover = rendered.match(/\{\{\s*[^}]+\}\}/g) || [];

const core = {
  client_name: { type: 'string', description: 'Customer name or empty string' },
  phone: { type: 'string', description: 'Phone or messenger contact or empty string' },
  service_interest: { type: 'string', description: 'Requested service or empty string' },
  city: { type: 'string', description: 'Customer city or empty string' },
  budget: { type: 'string', description: 'Stated budget or empty string' },
  preferred_time: { type: 'string', description: 'Preferred time or empty string' },
  language: { type: 'string', enum: ctx.languages, description: 'Customer language' }
};
for (const f of fields) core[f.key] = { type: 'string', description: f.description || f.label || f.key };
const schema = {
  type: 'object',
  properties: {
    reply: { type: 'string', description: 'Customer-facing reply' },
    is_lead: { type: 'boolean', description: 'true if the customer is a lead' },
    lead_status: { type: 'string', enum: cfg.qualification.statuses, description: 'Qualification status' },
    handover_required: { type: 'boolean', description: 'true if a manager must take over' },
    handover_reason: { type: 'string', description: 'Short reason for handover or empty string' },
    lead_data: { type: 'object', properties: core, required: Object.keys(core) },
    missing_fields: { type: 'array', items: { type: 'string' }, description: 'Required keys still missing' },
    summary: { type: 'string', description: 'Short neutral conversation summary' }
  },
  required: ['reply', 'is_lead', 'lead_status', 'handover_required', 'handover_reason', 'lead_data', 'missing_fields', 'summary']
};

const contract = [
  '',
  '## MACHINE OUTPUT CONTRACT',
  'Return ONLY a JSON object, no markdown, no code fences:',
  JSON.stringify(schema, null, 0),
  'Never invent values. Use empty strings for unknown fields.',
  'Known data: ' + JSON.stringify(known),
  'Missing required keys: ' + (missing.length ? missing.join(', ') : 'none'),
  'Allowed statuses: ' + cfg.qualification.statuses.join(', '),
  'Business: ' + cfg.business.name + '. Tone: ' + (cfg.business.communication_tone || 'neutral') + '.',
  cfg.qualification.lead_criteria.length ? 'Lead criteria: ' + cfg.qualification.lead_criteria.join('; ') : '',
  cfg.qualification.handover_criteria.length ? 'Handover criteria: ' + cfg.qualification.handover_criteria.join('; ') : '',
  'If the customer asks for a human, set handover_required=true.'
].filter(Boolean).join('\n');

const agentText = 'Customer message:\n' + String(ctx.text ?? '') + '\n\n' + contract;
const promptOk = !!basePrompt && missingKb.length === 0 && leftover.length === 0;
return [{ json: {
  ...ctx,
  system_prompt: rendered,
  schema_json: JSON.stringify(schema),
  lead_labels: labels,
  known_data: known,
  missing_fields: missing,
  agent_text: agentText,
  prompt_ok: promptOk,
  prompt_missing: missingKb.concat(leftover.map(x => x.replace(/[{}]/g, '').trim()))
} }];

const ctx = $('Render Prompt').first().json;
try { ctx.ai_usage = $input.first().json.usage ?? null; ctx.ai_end_ms = Date.now(); } catch (e) {}
const raw = $input.first().json.output ?? $input.first().json ?? {};
const fail = (msg) => [{ json: { ...ctx, valid: false, validation_error: msg } }];
let obj = raw;
if (typeof raw === 'string') {
  const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  try { obj = JSON.parse(cleaned); } catch (e) { return fail('json_parse_failed'); }
}
if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return fail('not_an_object');

const cfg = ctx.config;
const statuses = cfg.qualification.statuses;
const asStr = (v, max) => String(v ?? '').trim().slice(0, max);
const asBool = (v) => v === true || v === 'true';

let reply = asStr(obj.reply, 4000);
if (!reply) return fail('empty_reply');

const leadDataIn = (obj.lead_data && typeof obj.lead_data === 'object' && !Array.isArray(obj.lead_data)) ? obj.lead_data : {};
const allowed = new Set([...Object.keys(ctx.lead_labels ?? {}), ...ctx.required_keys, ...ctx.optional_keys]);
const lead_data = {};
for (const k of allowed) {
  const v = leadDataIn[k];
  lead_data[k] = asStr(Array.isArray(v) ? v.join(', ') : v, 300);
}
lead_data.language = asStr(lead_data.language || ctx.language_default, 20) || ctx.language_default;

let status = asStr(obj.lead_status, 30);
if (!statuses.includes(status)) status = 'in_progress';
let is_lead = asBool(obj.is_lead);
let handover = asBool(obj.handover_required);
let reason = asStr(obj.handover_reason, 300);

const missing = ctx.required_keys.filter(k => !String(lead_data[k] ?? '').trim());
if (status === 'qualified' && missing.length > 0) status = 'interested';
if (status === 'not_lead') { is_lead = false; handover = false; reason = ''; }
if (status === 'handover') handover = true;
if (['qualified', 'handover'].includes(status)) is_lead = true;
if (handover) {
  is_lead = true;
  status = 'handover';
  if (!reason) reason = 'manager handover required';
}
if (!handover && status === 'qualified' && cfg.qualification.handover_on_qualified) {
  handover = true;
  status = 'handover';
  if (!reason) reason = 'qualified lead ready for manager';
}

let summary = asStr(obj.summary, 800);
if (!summary) summary = ('Customer: ' + (ctx.text || '').slice(0, 200)).trim();

return [{ json: {
  ...ctx,
  valid: true,
  ai_usage: ctx.ai_usage ?? null,
  ai_end_ms: ctx.ai_end_ms ?? Date.now(),
  reply,
  is_lead,
  lead_status: status,
  handover_required: handover,
  handover_reason: reason,
  lead_data,
  missing_fields: missing,
  summary
} }];

const ctx = $input.first().json;
const limit = Math.max(200, Number(ctx.config.behavior.reply_chunk_limit ?? 950));
let text = String(ctx.reply ?? '').trim();
const chunks = [];
while (text.length > 0) {
  if (text.length <= limit) { chunks.push({ index: chunks.length, text }); break; }
  let cut = text.lastIndexOf('\n', limit);
  if (cut < limit - 300) cut = text.lastIndexOf(' ', limit);
  if (cut <= 0) cut = limit;
  chunks.push({ index: chunks.length, text: text.slice(0, cut).trim() });
  text = text.slice(cut).trim();
}
return [{ json: { ...ctx, chunks, chunks_count: chunks.length } }];

const safeAll = (name) => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };
const sent = safeAll('Log Sent');
const attempts = sent;
const base = $('Prepare Reply').first().json;
const usage = base.ai_usage ?? null;
const delivered = sent.length > 0;
const extracted = { ...(base.lead_data ?? {}), missing_fields: base.missing_fields ?? [] };
return [{ json: {
  ...base,
  extracted_b64: Buffer.from(JSON.stringify(extracted), 'utf8').toString('base64'),
  ig_send_status: delivered ? 200 : 0,
  chunks_sent: sent.length,
  send_attempts: attempts.length,
  tokens_in: usage?.prompt_tokens ?? usage?.input_tokens ?? null,
  tokens_out: usage?.completion_tokens ?? usage?.output_tokens ?? null,
  total_latency_ms: Math.max(0, Date.now() - Number(base.__start_ms ?? Date.now())),
  ai_latency_ms: Math.max(0, Number(base.ai_end_ms ?? 0) - Number(base.__start_ms ?? 0))
} }];

const s = $input.first().json;
const b64 = (v) => Buffer.from(String(v ?? ''), 'utf8').toString('base64');
const ld = s.lead_data ?? {};
return [{ json: {
  ...s,
  username_b64: b64(s.username),
  display_name_b64: b64(s.display_name),
  phone_b64: b64(ld.phone),
  service_b64: b64(ld.service_interest),
  city_b64: b64(ld.city),
  lead_data_b64: b64(JSON.stringify(ld)),
  summary_b64: b64(s.summary),
  handover_reason_b64: b64(s.handover_reason)
} }];

const base = $('Build Summary').first().json;
const up = $input.first().json ?? {};
const tg = base.config.integrations.telegram_enabled === true && base.config.notifications.telegram_chat_id !== '';
return [{ json: { ...base, lead_result: up,
  should_notify_handover: up.should_notify_handover === true && tg,
  should_notify_lead: up.should_notify_lead === true && tg
} }];

const s = $input.first().json;
const ld = s.lead_data ?? {};
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const label = (k) => esc(s.lead_labels?.[k] ?? k);
const rows = Object.keys(ld).filter(k => k !== 'language' && String(ld[k] ?? '').trim()).map(k => '• <b>' + label(k) + ':</b> ' + esc(ld[k]));
const profile = esc(s.event?.page_url || s.page_url || '—');
const text = [
  '🔔 <b>' + esc(s.config.business.name) + '</b>',
  '',
  '👤 <b>' + esc(s.display_name || ld.client_name || 'Customer') + '</b>',
  '🔗 ' + profile,
  '📞 ' + esc(ld.phone || '—'),
  '📦 <b>Status:</b> ' + esc(s.lead_status),
  '🎯 <b>Handover reason:</b> ' + esc(s.handover_reason || '—'),
  '',
  rows.join('\n'),
  '',
  '📝 <b>Summary:</b> ' + esc(s.summary || '—'),
  '💬 <b>Last message:</b> ' + esc(s.text || '—')
].join('\n');
return [{ json: { ...s, handover_text: text } }];

