  UPDATE leads SET handover_notified_at = now(), handover_reason = $4
  WHERE tenant_id = $1 AND channel = $2 AND customer_id = $3
  RETURNING 1
) SELECT 1 AS ok;

INSERT INTO metrics (
  tenant_id, channel, customer_id, message_id, message_type, message_length, language,
  ai_model, ai_latency_ms, total_latency_ms, is_lead, lead_status, handover_required,
  extracted_data, ig_send_status, chunks_count, tokens_in, tokens_out, execution_id
) VALUES (
  $1, $2, $3, NULLIF($4,''), $5, $6, $7, $8, $9, $10, $11::boolean, $12, $13::boolean,
  convert_from(decode($14,'base64'),'UTF8')::jsonb, $15, $16, $17, $18, $19
) RETURNING 1;

